import {
  Group,
  Mesh,
  PlaneGeometry,
  Vector2,
} from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture as textureNode,
  uv,
} from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();

  // Apply scene placement
  group.position.set(-3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Atlas region specification
  const atlasRegion = config.atlasRegion || { x: 0, y: 0, width: 512, height: 320 };

  // Create plane geometry with aspect ratio matching atlas region
  const aspectRatio = atlasRegion.width / atlasRegion.height;
  const geometry = new PlaneGeometry(aspectRatio, 1);

  // Load texture asset
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Calculate UV mapping for atlas region
  const atlasWidth = config.atlasWidth || atlasRegion.width;
  const atlasHeight = config.atlasHeight || atlasRegion.height;

  const uvOffset = new Vector2(
    atlasRegion.x / atlasWidth,
    atlasRegion.y / atlasHeight
  );
  const uvScale = new Vector2(
    atlasRegion.width / atlasWidth,
    atlasRegion.height / atlasHeight
  );

  // Create TSL-based material with texture and UV mapping
  const texNode = textureNode(texture);
  const uvNode = uv().mul(uvScale).add(uvOffset);

  const material = new MeshBasicNodeMaterial({
    colorNode: texNode(uvNode),
  });

  // Create and add mesh to group
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Setup resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Setup event handlers (empty for static card)
  group.userData.handlers = {};

  return group;
}
